const raw = [
  'POST /v1/users HTTP/1.1',
  'Host: api.example.com',
  'Content-Type: application/json',
  'Content-Length: 25',
  '',
  '{"name":"cppcat","age":1}',
].join('\r\n');

const sepAt = raw.indexOf('\r\n\r\n');
const head = raw.slice(0, sepAt);
const body = raw.slice(sepAt + 4);
const lines = head.split('\r\n');
const [requestLine, ...headerLines] = lines;

const m = requestLine.match(/^(\S+)\s+(\S+)\s+(HTTP\/[\d.]+)$/);
console.log('== 请求行 ==');
console.log('method  = ' + m[1]);
console.log('target  = ' + m[2]);
console.log('version = ' + m[3]);

console.log('== 头部 ==');
const headers = new Map();
for (const l of headerLines) {
  const i = l.indexOf(':');
  headers.set(l.slice(0, i).toLowerCase(), l.slice(i + 2));
}
for (const [k, v] of headers) console.log(k + ': ' + v);

console.log('== 主体 ==');
const bytes = Buffer.byteLength(body);
console.log('body = ' + body);
console.log('body 字节数 = ' + bytes);
console.log('与 Content-Length 一致: ' + (bytes === Number(headers.get('content-length'))));
console.log('');
console.log('空行（CRLF CRLF）是头部与主体的分界符；解析器逐行读到空行即停止解析头部。');
